export const APPLICATION_ID='splatters-video';

export const ICONS=Object.freeze(['shirt','globe','instagram','spotify','youtube','ticket','download','heart','facebook','tiktok','store','booking','email','external']);

export function youtubeId(value){try{const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password||u.port)return null;const host=u.hostname.replace(/^www\./,''),parts=u.pathname.split('/').filter(Boolean);let id=host==='youtu.be'?parts[0]:['youtube.com','m.youtube.com','youtube-nocookie.com'].includes(host)?u.pathname==='/watch'?u.searchParams.get('v'):['embed','shorts','live'].includes(parts[0])?parts[1]:null:null;return /^[a-zA-Z0-9_-]{11}$/.test(id||'')?id:null;}catch{return null;}}

export function externalURL(value){try{const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password||u.port||!u.hostname.includes('.')||/^(localhost|[\d.]+)$/.test(u.hostname)||/(^|\.)(local|lan|internal)$/.test(u.hostname)||u.hostname.startsWith('['))return null;return u.href;}catch{return null;}}

export function ctaURL(value){return /^mailto:[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,63}$/.test(value)?value:externalURL(value);}

export function validateConfig(value){if(value?.applicationId!==APPLICATION_ID||!((value.schemaVersion===1&&value.mode==='prototype')||(value.schemaVersion===2&&value.mode==='machine'&&/^[a-f0-9-]{36}$/.test(value.machineId||''))))throw Error('This prototype requires an independent Video configuration.');if(typeof value.creator!=='string'||!value.creator.trim()||value.creator.length>200||typeof value.title!=='string'||!value.title.trim()||value.title.length>250)throw Error('The demonstration needs a creator and video title.');const videoId=youtubeId(value.videoURL);if(!videoId)throw Error('Use a valid HTTPS YouTube video URL.');if(!Array.isArray(value.ctas)||value.ctas.length>10)throw Error('Invalid artist links');const ids=new Set(),ctas=[];for(const cta of value.ctas){const url=ctaURL(cta?.url);if(!url)continue;if(!/^[a-z][a-z0-9-]{0,60}$/.test(cta.id||'')||ids.has(cta.id)||typeof cta.label!=='string'||!cta.label.trim()||cta.label.length>40||!ICONS.includes(cta.icon))throw Error('Invalid or duplicated artist link.');ids.add(cta.id);ctas.push({...cta,label:cta.label.trim(),url});}const videos=value.videos??[{id:'video-'+videoId,videoURL:value.videoURL,title:value.title,creator:value.creator}];if(!Array.isArray(videos)||videos.length<1||videos.length>10)throw Error('Choose 1–10 videos.');const videoIds=new Set(),catalogueIds=new Set();const catalogue=videos.map(v=>{const id=youtubeId(v.videoURL);if(!id||!/^[-a-zA-Z0-9_]{1,80}$/.test(v.id||'')||videoIds.has(id)||catalogueIds.has(v.id)||typeof v.title!=='string'||!v.title.trim()||v.title.length>250||typeof v.creator!=='string'||!v.creator.trim()||v.creator.length>200)throw Error('Invalid or duplicate video catalogue entry.');videoIds.add(id);catalogueIds.add(v.id);return Object.freeze({...v,videoId:id});});return Object.freeze({...value,videoId,ctas,videos:Object.freeze(catalogue)});}

